def gen_fibonacci(n):
    """Generate Fibonacci numbers as generator"""
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

n = 1000

# Compare memory
list_fib = list_fibonacci(n)
gen_fib = gen_fibonacci(n)

print(f"List of {n} Fibonacci numbers: {sys.getsizeof(list_fib) / 1024:.2f} KB")
print(f"Generator: {sys.getsizeof(gen_fib)} bytes")
print(f"Memory ratio: {sys.getsizeof(list_fib) / sys.getsizeof(gen_fib):.0f}x")

