class WeakCache:
    def __init__(self):
        self._cache = {}

    def set(self, key, value):
        """Store value with weak reference"""
        self._cache[key] = weakref.ref(value)

    def get(self, key):
        """Retrieve value if still alive"""
        ref = self._cache.get(key)
        if ref is not None:
            obj = ref()
            if obj is not None:
                return obj
            else:
                del self._cache[key]
        return None

    def __len__(self):
        # Clean up dead references
        self._cache = {k: v for k, v in self._cache.items() if v() is not None}
        return len(self._cache)
